class Solution:
    def minAllOnesMultiple(self, k: int) -> int:
        if k % 2 == 0 or k % 5 == 0:
            return -1
        r = 0
        for t in range(1, k + 1):
            r = (r * 10 + 1) % k
            if r == 0:
                return t
        return -1

