class Solution {
public:
    int minAllOnesMultiple(int k) {
        unordered_set<int> seen;
        long long r = 0; int t = 0;
        while (true) {
            r = (r * 10 + 1) % k;
            t++;
            if (r == 0) return t;
            if (!seen.insert((int)r).second) return -1;
        }
    }
};

